package dev.raven.backup;
import android.content.Context;import android.content.pm.PackageManager;import org.json.*;import java.io.*;import java.util.*;
/** Prevalidates selected archives, then restores one archive at a time. */
final class RestoreQueue {
 interface Progress{void update(int current,int total,String name);}
 static final class Item{BackupCatalog.Entry entry;LiveRestore.Plan plan;Set<String> targets=new TreeSet<>();List<String> missing;}
 final LiveRestore restore;final List<Item> items=new ArrayList<>();final List<String> packages=new ArrayList<>();
 RestoreQueue(Context c){restore=new LiveRestore(c);}
 void prepare(List<BackupCatalog.Entry> entries)throws Exception{synchronized(LiveRestore.class){if(restore.pointer.exists())throw new IOException("Recover the pending restore first");Set<String> seen=new HashSet<>();try{for(BackupCatalog.Entry entry:entries){Item item=new Item();item.entry=entry;item.plan=restore.importArchive(entry.uri);items.add(item);restore.reviewEnvironment(item.plan);JSONArray apps=item.plan.manifest.getJSONArray("apps");for(int i=0;i<apps.length();i++){JSONObject saved=apps.getJSONObject(i);String pkg=saved.getString("package");if(!seen.add(pkg))throw new IOException("Choose only one backup version per app: "+AppNames.saved(restore.engine.c,saved,entry.uri));item.targets.add(pkg);packages.add(pkg);try{JSONObject now=restore.engine.info(pkg);if(now.getLong("version")!=saved.getLong("version")||!now.getJSONArray("signers").toString().equals(saved.getJSONArray("signers").toString()))throw new IOException("Installed version/signature differs: "+AppNames.saved(restore.engine.c,saved,entry.uri));}catch(PackageManager.NameNotFoundException absent){}}item.missing=ApkBackup.missing(restore.engine,item.plan.manifest,item.targets);if(item.missing.isEmpty())restore.prepare(item.plan,item.targets);}if(items.isEmpty())throw new IOException("No backups selected");}catch(Exception e){close();throw e;}}}
 boolean needsMigrationConsent(){for(Item item:items)if(!item.plan.migrationWarning.isEmpty())return true;return false;}
 void approveMigrations(){for(Item item:items)restore.approveMigration(item.plan);}
 String description()throws Exception{StringBuilder text=new StringBuilder();int index=0;for(Item item:items){List<String> names=new ArrayList<>();JSONArray apps=item.plan.manifest.getJSONArray("apps");for(int i=0;i<apps.length();i++)names.add(AppNames.saved(restore.engine.c,apps.getJSONObject(i),item.entry.uri));text.append(item.entry.recovery?"Recovery restore\n":"").append(++index).append(". ").append(String.join(", ",names)).append("\n").append(item.entry.name).append("\n").append(item.plan.migrationWarning.isEmpty()?FirmwareCheck.source(item.plan.manifest):item.plan.migrationWarning).append(item.missing.isEmpty()?"":"\nSaved installers will be installed for missing apps.").append("\n\n");}return text.toString();}
 String run(boolean keep,boolean launch,Progress progress)throws Exception{synchronized(LiveRestore.class){int completed=0;try{for(Item item:items){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Queue interrupted");progress.update(completed+1,items.size(),item.entry.name);FirmwareCheck.require(item.plan.manifest,item.plan.migrationApproval);ApkBackup.installMissing(restore.engine,item.plan.job,item.plan.manifest,item.targets,item.plan.migrationApproval);restore.prepare(item.plan,item.targets);String result=restore.restore(item.plan,keep,false);if(!result.startsWith("Restored "))throw new IOException(result);completed++;}String launches=launch?restore.launchRestored(packages):"Apps remain stopped; open them when ready.";return "Restored "+items.size()+" backups ("+packages.size()+" apps) in queue order. Contents, ownership, permissions and security labels verified.\n"+launches+"\n"+(keep?"Recovery backups saved. Clear them in Settings after confirming restored data.":"Temporary recovery copies removed after each successful restore.");}catch(Exception e){throw new IOException("Queue stopped after "+completed+" of "+items.size()+" backups. Earlier successful restores remain restored; later backups were not run.\n"+e.getMessage(),e);}finally{close();}}}
 void close(){String preserve=null;if(restore.pointer.exists())try{preserve=new JSONObject(BackupEngine.read(restore.pointer,1024*1024)).optString("incoming");}catch(Exception e){return;}for(Item item:items)if(item.plan!=null&&!item.plan.job.getPath().equals(preserve))restore.engine.clean(item.plan.job);}
}
